class AsyncFindTreeNode {
    get children() {
        return this.a.values();
    }
    constructor(element, id, b) {
        this.element = element;
        this.id = id;
        this.b = b;
        this.a = [];
    }
    addChild(child) {
        if (!this.b) {
            this.a.push(child);
            return;
        }
        const index = this.a.findIndex(existingChild => this.b.compare(child.element, existingChild.element) < 0);
        if (index !== -1) {
            this.a.splice(index, 0, child);
        }
        else {
            this.a.push(child);
        }
    }
}
